121	class LinearProbingHashMap implements IntMap {
122	    private static final int NOT_FOUND = -1;
123	
124	    private HashEntry[] table;
125	    private int size;
126	    private int capacity;
127	    private int deletedCount;
128	
129	    private ResizeStrategy resizeStrategy;
130	    private HashFunction hashFunction;
131	    private ProbeSequence probeSequence;
132	    private HashStats stats;
133	    private boolean trackStats;
134	
135	    public LinearProbingHashMap() {
136	        this(DefaultResizeStrategy.getMinCapacity(), true);
137	    }
138	
139	    public LinearProbingHashMap(int initialCapacity, boolean trackStats) {
140	        this(initialCapacity, new DefaultResizeStrategy(),
141	             new ModuloHashFunction(), new LinearProbeSequence(), trackStats);
142	    }
143	
144	    public LinearProbingHashMap(int initialCapacity, ResizeStrategy strategy,
145	                               HashFunction hash, ProbeSequence probe, boolean trackStats) {
146	        validateInitialCapacity(initialCapacity);
147	        this.capacity = normalizeCapacity(initialCapacity);
148	        this.size = 0;
149	        this.deletedCount = 0;
150	        this.table = new HashEntry[capacity];
151	        this.resizeStrategy = strategy;
152	        this.hashFunction = hash;
153	        this.probeSequence = probe;
154	        this.trackStats = trackStats;
155	        this.stats = new HashStats();
156	    }
157	
158	    @Override
159	    public void put(int key, int value) {
160	        if (resizeStrategy.shouldExpand(size, deletedCount, capacity)) {
161	            resize(resizeStrategy.nextCapacity(capacity, true));
162	        }
163	
164	        int index = findSlot(key);
165	        if (index < 0) {
166	            throw new RuntimeException("Hash table full - probe sequence exhausted");
167	        }
168	
169	        boolean isNewEntry = table[index] == null || !table[index].isActive();
170	        if (table[index] != null && table[index].deleted) {
171	            deletedCount--;
172	        }
173	
174	        table[index] = new HashEntry(key, value);
175	        if (isNewEntry) {
176	            size++;
177	        }
178	    }
179	
180	    @Override
181	    public int get(int key) {
182	        int index = findExisting(key);
183	        return index >= 0 ? table[index].value : NOT_FOUND;
184	    }
185	
186	    @Override
187	    public int remove(int key) {
188	        int index = findExisting(key);
189	        if (index >= 0) {
190	            int value = table[index].value;
191	            table[index].markDeleted();
192	            size--;
193	            deletedCount++;
194	
195	            if (resizeStrategy.shouldShrink(size, capacity)) {
196	                resize(resizeStrategy.nextCapacity(capacity, false));
197	            }
198	            return value;
199	        }
200	        return NOT_FOUND;
201	    }
202	
203	    @Override
204	    public int size() {
205	        return size;
206	    }
207	
208	    @Override
209	    public boolean isEmpty() {
210	        return size == 0;
211	    }
212	
213	    @Override
214	    public boolean containsKey(int key) {
215	        return findExisting(key) >= 0;
216	    }
217	
218	    @Override
219	    public void clear() {
220	        size = 0;
221	        deletedCount = 0;
222	        table = new HashEntry[capacity];
223	        stats.reset();
224	    }
225	
226	    public void printStats() {
227	        if (trackStats) {
228	            System.out.println("Hash Table Statistics:");
229	            System.out.println("  Size: " + size + "/" + capacity);
230	            System.out.println("  Load Factor: " + String.format("%.2f", (float) size / capacity));
231	            stats.print();
232	        }
233	    }
234	
235	    public void display() {
236	        System.out.println("=== Hash Table ===");
237	        for (int i = 0; i < capacity; i++) {
238	            HashEntry entry = table[i];
239	            if (entry == null) {
240	                System.out.println("[" + i + "] EMPTY");
241	            } else if (entry.isActive()) {
242	                System.out.println("[" + i + "] " + entry.key + " -> " + entry.value);
243	            } else {
244	                System.out.println("[" + i + "] DELETED");
245	            }
246	        }
247	        System.out.println("Size: " + size + ", Capacity: " + capacity +
248	                          ", Deleted: " + deletedCount);
249	    }
250	
251	    private int findSlot(int key) {
252	        int startIndex = hashFunction.hash(key, capacity);
253	        int firstDeleted = -1;
254	
255	        for (int i = 0; i < capacity; i++) {
256	            int probeIndex = probeSequence.nextProbe(startIndex, i, capacity);
257	            HashEntry entry = table[probeIndex];
258	
259	            if (trackStats && i > 0) {
260	                stats.recordProbe(i);
261	            }
262	
263	            if (entry == null) {
264	                return firstDeleted >= 0 ? firstDeleted : probeIndex;
265	            }
266	            if (entry.matches(key)) {
267	                return probeIndex;
268	            }
269	            if (entry.deleted && firstDeleted < 0) {
270	                firstDeleted = probeIndex;
271	                if (trackStats) stats.recordCollision();
272	            }
273	        }
274	        return -1;
275	    }
276	
277	    private int findExisting(int key) {
278	        int startIndex = hashFunction.hash(key, capacity);
279	
280	        for (int i = 0; i < capacity; i++) {
281	            int probeIndex = probeSequence.nextProbe(startIndex, i, capacity);
282	            HashEntry entry = table[probeIndex];
283	
284	            if (trackStats && i > 0) {
285	                stats.recordProbe(i);
286	            }
287	
288	            if (entry == null) {
289	                return -1;
290	            }
291	            if (entry.matches(key)) {
292	                return probeIndex;
293	            }
294	        }
295	        return -1;
296	    }
297	
298	    private void resize(int newCapacity) {
299	        if (newCapacity == capacity) {
300	            return;
301	        }
302	
303	        HashEntry[] oldTable = table;
304	        capacity = newCapacity;
305	        table = new HashEntry[capacity];
306	        size = 0;
307	        deletedCount = 0;
308	        stats.reset();
309	
310	        for (HashEntry entry : oldTable) {
311	            if (entry != null && entry.isActive()) {
312	                put(entry.key, entry.value);
313	            }
314	        }
315	    }
316	
317	    private void validateInitialCapacity(int capacity) {
318	        if (capacity < DefaultResizeStrategy.getMinCapacity()) {
319	            throw new IllegalArgumentException("Capacity below minimum: " +
320	                DefaultResizeStrategy.getMinCapacity());
321	        }
322	        if (capacity > DefaultResizeStrategy.getMaxCapacity()) {
323	            throw new IllegalArgumentException("Capacity exceeds maximum: " +
324	                DefaultResizeStrategy.getMaxCapacity());
325	        }
326	    }
327	
328	    private int normalizeCapacity(int capacity) {
329	        if (PowerOfTwo.isPowerOfTwo(capacity)) {
330	            return capacity;
331	        }
332	        return PowerOfTwo.nextPowerOfTwo(capacity,
333	            DefaultResizeStrategy.getMaxCapacity());
334	    }
335	}
