337	class PowerOfTwo {
338	    private static final int MAX_POWER_OF_TWO = 1 << 30;
339	
340	    static boolean isPowerOfTwo(int n) {
341	        return n > 0 && (n & (n - 1)) == 0;
342	    }
343	
344	    static int nextPowerOfTwo(int n, int max) {
345	        int power = 1;
346	        while (power < n && power < max) {
347	            power <<= 1;
348	        }
349	        return power;
350	    }
351	}
